def main():
    out = {lang: {} for lang in LANGS}
    for key, row in T.items():
        assert len(row) == len(LANGS), f"{key}: expected {len(LANGS)} translations, got {len(row)}"
        for lang, text in zip(LANGS, row):
            out[lang][key] = text
    # every problem needs a name key + every template referenced must exist
    for p in KB["problems"]:
        assert f"n_{p['id']}" in T, p["id"]
        for tier in p["tiers"].values():
            for a in tier:
                assert f"a_{a[0]}" in T, a
                for arg in a[1:]:
                    if arg.startswith("@"):
                        assert f"p_{arg[1:]}" in T, arg
    for s in KB["symptoms"]:
        assert f"sym_{s}" in T, s
    (OUT / "i18n.json").write_text(json.dumps(out, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    (OUT / "kb.json").write_text(json.dumps(KB, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"i18n: {len(T)} keys x {len(LANGS)} languages; kb: {len(KB['problems'])} problems")

if __name__ == "__main__":
    main()
